    test('Dont build modules from test.ts files', async () => {
        // relies on default settings for ignored extensions
        const rootDir = path.resolve(__dirname, 'apps', 'ts-test')
        const project = new Project({ compiler: ctx.getCompiler(), rootDir })
        project.registerExplicitId('sys_module', 'src_server_script_ts', '11111')

        const output = Object.fromEntries(
            (await project.getOutput()).map((file) => [path.relative(rootDir, file.path), file.content])
        )

        expect(output['dist/app/update/sys_script_12345.xml']).toMatch(
            "require('sn_app_a/ts-test/0.0.1/src/server/script.ts')"
        )

        expect(output['dist/app/update/sys_module_11111.xml']).toMatch(
            '<path>sn_app_a/ts-test/0.0.1/src/server/script.ts</path>'
        )

        // sys_module_script, sys_script, sys_script, sys_module_package.json, sys_app
        expect(Object.entries(output).length).toBe(6)

        Object.values(output).forEach((file) => {
            expect(file).not.toMatch('<path>sn_app_a/ts-test/0.0.1/src/server/script.test.ts</path>')
        })
    })

