    test('TypeScript transpilation should respect custom tsconfig used and capture all diagnostic errors', async () => {
        const rootDir = path.resolve(__dirname, 'apps', 'diagnostic-failures')
        const project = new Project({ compiler: ctx.getCompiler(), rootDir })
        const diagnostics = await project.getDiagnostics()
        expect(diagnostics.length).toBeGreaterThan(0)
        const diagnosticStrings = diagnostics.map((diag) => diag.message.trim())
        expect(diagnosticStrings).toContain(
            "Cannot find module '@servicenow/glide' or its corresponding type declarations."
        )
        expect(diagnosticStrings).toContain(
            "Argument of type 'number' is not assignable to parameter of type 'string'."
        )
        expect(diagnosticStrings).toContain("Parameter 'b' implicitly has an 'any' type.")
        expect(diagnosticStrings).toContain(
            "File 'diagnostic-failures/src/server/another/excluded.ts' is not included in project. Check your tsconfig: diagnostic-failures/tsconfig.json"
        )
        const output = await project.getOutput()
        expect(output).toHaveLength(5)
    })

    test('DEF0652475: Build produces both module and typescript diagnostics for missing module path, typescript erros and missing dependencies inside package.json ', async () => {
        const rootDir = path.resolve(__dirname, 'apps', 'mod-diag')
        const project = new Project({ compiler: ctx.getCompiler(), rootDir })
        const diagnostics = await project.getDiagnostics()
        expect(diagnostics).toHaveLength(3)
        const expectedDiagnostics = [
            {
                message: `Dependency lodash is not found in package.json`,
                source: 'fluent',
            },
            {
                message: `Module path was mapped from '${rootDir}/src/server/unmapped.ts' to '${rootDir}/js/server/unmapped.js' but no file exists at the mapped location.`,
                source: 'fluent',
            },
            {
                message: `Unable to resolve the script reference, ensure the imported module is within the src/server directory.`,
                source: 'fluent',
            },
        ]
        expectedDiagnostics.forEach((expected) => {
            expect(diagnostics.some((d) => d.message === expected.message && d.source === expected.source)).toBe(true)
        })
    })

    test('ts type only imports do not produce diagnostic errors when specified in devDependencies', async () => {
        const vol = new memfs.Volume()

        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const logger = createConsoleLogger()

        // Populate the memfs volume with @types/jest declaration
        vol.fromJSON({
            '/node_modules/@jest/types/package.json': JSON.stringify({
                name: '@jest/types',
                version: '29.5.0',
                types: 'index.d.ts',
            }),
            '/node_modules/@jest/types/index.d.ts': `
export namespace Config {
    export type InitialOptions = any
}
`,
        })

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            packageJson: {
                name: 'test',
                version: '1.0.0',
                dependencies: {},
                devDependencies: { '@types/jest': 'latest' },
            },
        })

        project.addFile({
            path: '/src/server/typesimport.ts',
            content: `import type * as jest from '@jest/types'
const foo: jest.Config.InitialOptions = {}
console.log(foo)
`,
        })

        project.addFile({
            path: '/src/server/typesimport2.ts',
            content: `import type { Config } from '@jest/types'
const foo: Config.InitialOptions = {}
console.log(foo)
`,
        })

        const diagnostics = await project.getDiagnostics()
        expect(diagnostics.length).toBe(0)

        const output = await project.getOutput()

        const moduleOutput = output.find((f) => f.content.includes('x_test/test/1.0.0/src/server/typesimport2.ts'))
        expect(moduleOutput).toBeDefined()

        //Ensure the import was removed from the outputed module
        expect(moduleOutput?.content).toContain(`<content><![CDATA[const foo = {};`)
    })

