describe('Trusted modules tests', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'apps') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    beforeEach(() => {
        clearDependencyCache()
    })

    test('Trusted modules should have external_source set to false', async () => {
        // Uses the trusted-modules test app which has crypto-js as a trusted module
        const rootDir = path.resolve(__dirname, 'apps', 'trusted-modules')
        const project = new Project({ compiler: ctx.getCompiler(), rootDir })

        // Register explicit ID for the crypto-js package.json (key format: name@version/file)
        project.registerExplicitId('sys_module', 'crypto-js@4.2.0/package.json', 'trusted11111')

        const output = Object.fromEntries(
            (await project.getOutput()).map((file) => [path.relative(rootDir, file.path), file.content])
        )

        // Trusted module should have external_source=false
        expect(output['dist/app/update/sys_module_trusted11111.xml']).toMatch(
            '<external_source>false</external_source>'
        )
    })

    test('Untrusted modules should have external_source set to true', async () => {
        // Uses the validate-SBOM test app which has crypto-js but NO trustedModules config
        const rootDir = path.resolve(__dirname, 'apps', 'validate-SBOM')
        const project = new Project({ compiler: ctx.getCompiler(), rootDir })

        // Register explicit ID for the crypto-js package.json (key format: name@version/file)
        project.registerExplicitId('sys_module', 'crypto-js@4.2.0/package.json', 'untrusted2222')

        const output = Object.fromEntries(
            (await project.getOutput()).map((file) => [path.relative(rootDir, file.path), file.content])
        )

        // Untrusted module (no trustedModules config) should have external_source=true
        expect(output['dist/app/update/sys_module_untrusted2222.xml']).toMatch(
            '<external_source>true</external_source>'
        )
    })
})
